import { useMemo, useState } from 'react';
import {
  Badge,
  Button,
  Card,
  Chip,
  ChipGroup,
  CircularProgress,
  Divider,
  EmptyState,
  Inline,
  Pagination,
  Stack,
  Text,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'archived' | 'over_quota';

type Project = {
  id: string;
  name: string;
  spent: number;
  quota: number;
  status: ProjectStatus;
};

type ProjectSpendPanelProps = {
  projects: Project[];
  pageSize?: number;
};

const STATUS_META: Record<ProjectStatus, { label: string; tone: string }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  archived: { label: 'В архиве', tone: 'neutral' },
  over_quota: { label: 'Превышение квоты', tone: 'danger' },
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'paused', 'over_quota', 'archived'];

function usagePercent(project: Project): number {
  if (project.quota <= 0) return 0;
  return Math.min(100, Math.max(0, Math.round((project.spent / project.quota) * 100)));
}

function usageTone(percent: number): string {
  if (percent >= 100) return 'danger';
  if (percent >= 80) return 'warning';
  return 'success';
}

export default function ProjectSpendPanel({ projects, pageSize = 5 }: ProjectSpendPanelProps) {
  const [selected, setSelected] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => (selected.length === 0 ? projects : projects.filter((p) => selected.includes(p.status))),
    [projects, selected],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const currentPage = Math.min(page, pageCount);
  const rows = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const toggleStatus = (status: ProjectStatus) => {
    setPage(1);
    setSelected((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status],
    );
  };

  const resetFilters = () => {
    setSelected([]);
    setPage(1);
  };

  return (
    <Card padding="lg">
      <Stack gap="lg">
        <Stack gap="xs">
          <Text as="h2" size="lg" weight="bold">
            Расход по проектам
          </Text>
          <Text size="sm" tone="muted">
            Показано {filtered.length} из {projects.length}
          </Text>
        </Stack>

        <ChipGroup aria-label="Фильтр по статусу">
          {STATUS_ORDER.map((status) => {
            const isSelected = selected.includes(status);
            return (
              <Chip
                key={status}
                selected={isSelected}
                aria-pressed={isSelected}
                onClick={() => toggleStatus(status)}
                onRemove={isSelected ? () => toggleStatus(status) : undefined}
              >
                {STATUS_META[status].label}
              </Chip>
            );
          })}
        </ChipGroup>

        <Divider />

        {rows.length === 0 ? (
          <EmptyState
            title="Ничего не найдено"
            description="Под выбранные статусы не подходит ни один проект."
            action={
              <Button variant="primary" onClick={resetFilters}>
                Сбросить фильтры
              </Button>
            }
          />
        ) : (
          <Stack gap="md">
            <Stack as="ul" gap="sm" role="list">
              {rows.map((project) => {
                const percent = usagePercent(project);
                const meta = STATUS_META[project.status];
                return (
                  <Inline
                    as="li"
                    key={project.id}
                    align="center"
                    justify="between"
                    gap="md"
                    style={{
                      paddingBlock: 'var(--jx-space-sm)',
                      borderBottom: '1px solid var(--jx-color-border-subtle)',
                    }}
                  >
                    <Inline align="center" gap="md">
                      <CircularProgress
                        value={percent}
                        max={100}
                        size="sm"
                        tone={usageTone(percent)}
                        aria-label={`Квота проекта ${project.name} заполнена на ${percent}%`}
                      >
                        <Text size="xs" weight="medium">
                          {percent}%
                        </Text>
                      </CircularProgress>
                      <Stack gap="2xs">
                        <Text weight="medium">{project.name}</Text>
                        <Text size="sm" tone="muted">
                          {project.spent} / {project.quota}
                        </Text>
                      </Stack>
                    </Inline>
                    <Badge tone={meta.tone}>{meta.label}</Badge>
                  </Inline>
                );
              })}
            </Stack>

            {pageCount > 1 && (
              <Inline justify="end">
                <Pagination page={currentPage} pageCount={pageCount} onPageChange={setPage} />
              </Inline>
            )}
          </Stack>
        )}
      </Stack>
    </Card>
  );
}

